function crossAnchorKeys(item) {
    var it = item || {};
    var key = String(it.key || '');
    var keys = [];
    if (key.indexOf('pr-') === 0 &&
        it.issueNumber !== undefined && it.issueNumber !== null) {
        keys.push('gh-' + it.issueNumber);
    } else if (key.indexOf('gh-') === 0 &&
        it.prNumber !== undefined && it.prNumber !== null) {
        keys.push('pr-' + it.prNumber);
    }
    return keys;
}

// gh-744: the stub-title anchor is a WHOLE token. A plain substring match
// collided on key prefixes — the guard for 'gh-1274' matched
// '▶ rework (SM) · gh-12749' (a DIFFERENT issue's in-flight leg) and
// review-after-dev never dispatched after the rework leg finished (live
// fa gh-1274: no review leg for 3+ h until a manual dispatch). What may
// follow the anchor token: [REDACTED:Sensitive Value] (EOL), the stub's second anchor line
// ('\n· gh-<key>'), or the ': <issue title>' suffix. What must NOT follow
// it: a key-extending character (digits/letters extend the number;
// '-' continues a compound key) — that token belongs to a different item.
function isAnchorKeyChar(ch) {
    return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') ||
           (ch >= 'A' && ch <= 'Z') || ch === '-';
}

// gh-944: the factory's own run-name shape is "#<issue>" — the ai-teammate
// stub names its runs "teammate: issues #925" (event echo) and
// "teammate: workflow_dispatch #925 <leg>" (dispatches). The stub anchor
// token alone never matched those, so an in-flight EVENT run (or a
// previously dispatched SM leg) did not suppress a dev-on-assignment
// dispatch and every tick re-fired the leg behind the per-issue concurrency
// group. gh-<digits> keys therefore also match the '#<digits>' token under
// the SAME whole-token boundaries (a trailing key char — '#9251' — never
// matches). PR keys are unchanged: their run titles carry no number today,
// and a PR number and an issue number are different entities — '#925' must
// never key a 'pr-925' anchor.
function anchorTokens(ticketKey) {
    var tokens = ['· ' + ticketKey];
    var m = /^gh-(\d+)$/.exec(String(ticketKey));
    if (m) tokens.push('#' + m[1]);
    return tokens;
}

function stubAnchorMatches(runName, ticketKey) {
