    // the dev-on-assignment rule re-derives dev legs for issues assigned to
    // THE MACHINE (resolveAssigneeQuery; fail-closed when unresolvable).
    var assigneeQuery = resolveAssigneeQuery(q.assignee, machineAuthor);
